UPDATE friend
SET status = 'PENDING',
    created_at = CURRENT_TIMESTAMP(6)
WHERE id = #{relationId}
  AND user_id = #{requesterId}
  AND friend_id = #{receiverId}
  AND status = 'REJECTED'

UPDATE friend
SET status = #{targetStatus}
WHERE id = #{requestId}
  AND friend_id = #{receiverId}
  AND status = #{expectedStatus}
